def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # Identify the sparse marker color in this row.
        counts = {v: row.count(v) for v in set(row)}
        markers = [v for v in counts if v != max(counts, key=counts.get)]
        if not markers:
            continue
        marker = markers[0]
        for c in range(len(row) - 2):
            if row[c] == marker and row[c + 2] == marker and row[c + 1] != marker:
                out[r][c + 1] = 2
    return out
